// Squeezy Duplicator: deep-duplicate comps so every nested precomp becomes its own copy
var roots = [];
var psel = app.project.selection;
for (var i = 0; i < psel.length; i++) if (psel[i] instanceof CompItem) roots.push(psel[i]);
if (!roots.length && comp) roots.push(comp);
if (!roots.length) return "Select a comp in the Project panel (or open one).";

var suffix = String(params.suffix || ""), find = String(params.find || ""), repl = String(params.replace || "");
if (!suffix && !find) suffix = "_copy";
var keepWords = [];
var kw = String(params.keep || "").split(",");
for (var k = 0; k < kw.length; k++) { var w = kw[k].replace(/^\s+|\s+$/g, ""); if (w) keepWords.push(w.toLowerCase()); }

function newName(n) {
    var s = String(n);
    if (find) s = s.split(find).join(repl);
    if (suffix) s = s + suffix;
    if (s === String(n)) s = s + "_copy";
    return s;
}
function isShared(c) {
    var n = String(c.name).toLowerCase();
    for (var i = 0; i < keepWords.length; i++) if (n.indexOf(keepWords[i]) >= 0) return true;
    return false;
}

// folders: one new folder per run, mirroring sub-folders of the originals
var baseFolder = roots[0].parentFolder, outFolder = null, sub = {};
if (params.folder) {
    outFolder = app.project.items.addFolder(newName(roots[0].name) + " (Squeezy)");
    outFolder.parentFolder = baseFolder;
}
function folderFor(c) {
    if (!outFolder) return c.parentFolder;
    var pf = c.parentFolder;
    if (!pf || pf === baseFolder || pf === app.project.rootFolder) return outFolder;
    if (!sub[pf.id]) { sub[pf.id] = app.project.items.addFolder(pf.name); sub[pf.id].parentFolder = outFolder; }
    return sub[pf.id];
}

var map = {}, made = [], renames = [], shared = 0;
function dup(c, isRoot) {
    if (map[c.id]) return map[c.id];
    if (!isRoot && isShared(c)) { map[c.id] = c; shared++; return c; }   // the comp you picked is always copied
    var d = c.duplicate();
    d.name = newName(c.name);
    d.parentFolder = folderFor(c);
    map[c.id] = d;
    made.push(d);
    renames.push([c.name, d.name]);
    for (var i = 1; i <= d.numLayers; i++) {
        var L = d.layer(i);
        if (L.source && L.source instanceof CompItem) {
            var nd = dup(L.source);
            if (nd !== L.source) L.replaceSource(nd, false);
        }
    }
    return d;
}
var tops = [];
for (var r = 0; r < roots.length; r++) {
    tops.push(dup(roots[r], true));
}

// point expressions at the new comps (comp("Old") -> comp("New"))
var fixed = 0;
function fixExpr(group) {
    for (var i = 1; i <= group.numProperties; i++) {
        var p = group.property(i);
        if (p.propertyType === PropertyType.PROPERTY) {
            if (p.canSetExpression && p.expression) {
                var e = p.expression, e2 = e;
                for (var j = 0; j < renames.length; j++) {
                    e2 = e2.split('comp("' + renames[j][0] + '")').join('comp("' + renames[j][1] + '")');
                    e2 = e2.split("comp('" + renames[j][0] + "')").join("comp('" + renames[j][1] + "')");
                }
                if (e2 !== e) { try { p.expression = e2; fixed++; } catch (er) {} }
            }
        } else if (p.numProperties) fixExpr(p);
    }
}
if (params.expressions) {
    for (var m = 0; m < made.length; m++) for (var l = 1; l <= made[m].numLayers; l++) fixExpr(made[m].layer(l));
}
if (params.open && tops.length) { try { tops[0].openInViewer(); } catch (eo) {} }

return "Squeezy Duplicator: " + made.length + " comp" + (made.length === 1 ? "" : "s") + " copied"
    + (shared ? ", " + shared + " kept shared" : "") + (fixed ? ", " + fixed + " expression" + (fixed === 1 ? "" : "s") + " re-linked" : "");

// ---- Squeezy add-on helpers (ExtendScript, ES3) ----
function sqFx(l) { return l.property("ADBE Effect Parade"); }
function sqCtrl(l, match, name, v) {
    var p = sqFx(l).property(name);
    if (p && p.matchName !== match) { p.remove(); p = null; }
    if (!p) { p = sqFx(l).addProperty(match); p.name = name; p = sqFx(l).property(name); }
    try { if (v !== undefined && v !== null) p.property(1).setValue(v); } catch (e) {}
    return sqFx(l).property(name);
}
function sqSlider(l, name, v) { return sqCtrl(l, "ADBE Slider Control", name, v); }
function sqCheckbox(l, name, v) { return sqCtrl(l, "ADBE Checkbox Control", name, v ? 1 : 0); }
function sqHex(h) { var n = parseInt(String(h).replace("#", ""), 16); return [((n >> 16) & 255) / 255, ((n >> 8) & 255) / 255, (n & 255) / 255, 1]; }
function sqRemoveFx(l, prefix) {
    var fx = sqFx(l); if (!fx) return;
    for (var i = fx.numProperties; i >= 1; i--) if (String(fx.property(i).name).indexOf(prefix) === 0) fx.property(i).remove();
}
function sqRemoveKids(comp, l, prefix) {
    for (var i = comp.numLayers; i >= 1; i--) {
        var c = comp.layer(i);
        if (c.parent && c.parent.index === l.index && String(c.name).indexOf(prefix) === 0) c.remove();
    }
}
function sqEaseKeys(prop) {
    for (var k = 1; k <= prop.numKeys; k++) {
        var dims = 1; try { var v = prop.keyValue(k); if (v instanceof Array) dims = v.length; } catch (e) {}
        if (prop.propertyValueType === PropertyValueType.TwoD_SPATIAL || prop.propertyValueType === PropertyValueType.ThreeD_SPATIAL) dims = 1;
        var a = [], b = [];
        for (var d = 0; d < dims; d++) { a.push(new KeyframeEase(0, 45)); b.push(new KeyframeEase(0, 45)); }
        try { prop.setTemporalEaseAtKey(k, a, b); } catch (e2) {}
    }
}

// ---- pixel grid reveal (used by Pixel Scan Reveal and Block Flow) ----
// Builds a block matte + optional glowing block layer, both parented to the target layer.
function sqScan(comp, l, o) {
    var r = l.sourceRectAtTime(o.t0, false);
    if (!r || r.width < 1 || r.height < 1) throw new Error(l.name + " has nothing visible at the current time");
    var size = Math.max(4, o.size), cols, rows;
    do { cols = Math.ceil(r.width / size); rows = Math.ceil(r.height / size); if (cols * rows > 700) size *= 1.15; } while (cols * rows > 700);

    sqRemoveKids(comp, l, "SQ Scan ");
    sqRemoveFx(l, "SQ Scan ");
    sqSlider(l, "SQ Scan Progress", 0);
    sqSlider(l, "SQ Scan Random", o.random);
    sqSlider(l, "SQ Scan Glow Band", o.band);
    var pr = sqFx(l).property("SQ Scan Progress").property(1);
    pr.setValueAtTime(o.t0, 0);
    pr.setValueAtTime(o.t0 + o.dur, 100);
    sqEaseKeys(pr);

    var cells = [];
    for (var y = 0; y < rows; y++) for (var x = 0; x < cols; x++) {
        var cx = r.left + (x + 0.5) * size, cy = r.top + (y + 0.5) * size, u;
        var nx = cols > 1 ? x / (cols - 1) : 0, ny = rows > 1 ? y / (rows - 1) : 0;
        switch (o.dir) {
            case "rtl": u = 1 - nx; break;
            case "ttb": u = ny; break;
            case "btt": u = 1 - ny; break;
            case "center": u = Math.min(1, Math.sqrt((nx - 0.5) * (nx - 0.5) + (ny - 0.5) * (ny - 0.5)) / 0.7072); break;
            case "random": u = Math.random(); break;
            default: u = nx;
        }
        cells.push({ x: cx, y: cy, u: u, q: Math.random() });
    }

    function grid(name, glow) {
        var s = comp.layers.addShape();
        s.name = name;
        s.moveBefore(l);
        s.parent = l;
        try { s.property("ADBE Transform Group").property("ADBE Anchor Point").setValue([0, 0]); } catch (e) {}
        try { s.property("ADBE Transform Group").property("ADBE Position").setValue([0, 0]); } catch (e1) { try { s.property("ADBE Transform Group").property("ADBE Position").setValue([0, 0, 0]); } catch (e2) {} }
        var root = function () { return s.property("ADBE Root Vectors Group"); };
        var bs = glow ? size * 0.78 : size + 1;
        var col = glow ? sqHex(o.color) : [1, 1, 1, 1];
        for (var i = 0; i < cells.length; i++) {
            var c = cells[i], k = (c.u * 1).toFixed(4), qq = c.q.toFixed(4);
            var gi = root().addProperty("ADBE Vector Group").propertyIndex;
            var G = function () { return root().property(gi); };
            G().property("ADBE Vectors Group").addProperty("ADBE Vector Shape - Rect");
            G().property("ADBE Vectors Group").property(1).property("ADBE Vector Rect Size").setValue([bs, bs]);
            G().property("ADBE Vectors Group").addProperty("ADBE Vector Graphic - Fill");
            G().property("ADBE Vectors Group").property(2).property("ADBE Vector Fill Color").setValue(col);
            var T = G().property("ADBE Vector Transform Group");
            T.property("ADBE Vector Position").setValue([c.x, c.y]);
            var head = "var P=parent.effect(\"SQ Scan Progress\")(1)/100, R=parent.effect(\"SQ Scan Random\")(1)/100; var k=" + k + "*(1-R)+" + qq + "*R*0.999;";
            G().property("ADBE Vector Transform Group").property("ADBE Vector Group Opacity").expression = glow
                ? head + " var B=Math.max(parent.effect(\"SQ Scan Glow Band\")(1)/100,0.001), d=P-k*(1-B)-B*0.5; (P>0 && P<1 && d>=-B*0.5 && d<B*0.5) ? 100*(1-Math.abs(d)/(B*0.5)) : 0;"
                : head + " (P>=1 || (P>0 && P>=k)) ? 100 : 0;";
        }
        return s;
    }

    var m = grid("SQ Scan Matte · " + l.name, false);
    if (o.glow) {
        var g = grid("SQ Scan Glow · " + l.name, true);
        g.blendingMode = BlendingMode.ADD;
        var gl = sqFx(g).addProperty("ADBE Glo2");
        try { gl.property(3).setValue(Math.max(10, size * 0.8)); gl.property(4).setValue(1.6); } catch (eg) {}
    }
    var done = false;
    try { if (l.setTrackMatte) { l.setTrackMatte(m, TrackMatteType.ALPHA); done = true; } } catch (et) {}
    if (!done) { m.moveBefore(l); l.trackMatteType = TrackMatteType.ALPHA; }
    m.enabled = false;
    return cells.length;
}

if (!comp) return "Open a composition first.";
var MODES = { "Middle of each word": 0, "After first letter": 1, "Longest word only": 2, "Every connection": 3 };
var mode = MODES[params.position]; if (mode === undefined) mode = 0;
var n = 0, skipped = 0;
var expr = [
 "var N=effect(\"SQ Kashida Amount\")(1), D=Math.max(effect(\"SQ Kashida Duration\")(1),0.01), B=effect(\"SQ Kashida Bounce\")(1)/100;",
 "var t=time-inPoint-effect(\"SQ Kashida Delay\")(1), p=Math.min(Math.max(t/D,0),1);",
 "var c1=2.6*B, c3=c1+1, e=(p<=0)?0:((p>=1)?1:1+c3*Math.pow(p-1,3)+c1*Math.pow(p-1,2));",
 "if (effect(\"SQ Kashida Collapse\")(1)==1){ var po=Math.min(Math.max((outPoint-time)/D,0),1); e=Math.min(e, 1-Math.pow(1-po,3)); }",
 "var K=Math.max(0,Math.round(N*e)), s=''+value, MODE=" + mode + ";",
 "function ar(c){ var x=c.charCodeAt(0); return (x>=0x0620&&x<=0x064A)||(x>=0x066E&&x<=0x06D3); }",
 "function joins(c){ return ar(c) && 'اأإآٱدذرزوؤةءژ'.indexOf(c)<0; }",
 "var spots=[], words=[], st=-1;",
 "for (var i=0;i<=s.length;i++){ var ch=i<s.length?s.charAt(i):' '; if(ar(ch)||ch=='\\u0640'){ if(st<0) st=i; } else if(st>=0){ words.push([st,i]); st=-1; } }",
 "function cand(w){ var r=[]; for(var j=w[0];j<w[1]-1;j++){ if(joins(s.charAt(j)) && ar(s.charAt(j+1))) r.push(j+1); } return r; }",
 "if (MODE==2){ var best=null; for (var w=0;w<words.length;w++) if(!best||words[w][1]-words[w][0]>best[1]-best[0]) best=words[w]; if(best) words=[best]; }",
 "for (var w2=0; w2<words.length; w2++){ var c=cand(words[w2]); if(!c.length) continue;",
 "  if (MODE==3) spots=spots.concat(c); else if (MODE==1) spots.push(c[0]); else spots.push(c[Math.floor((c.length-1)/2)]); }",
 "var out='', last=0, run=''; for (var q=0;q<K;q++) run+='\\u0640';",
 "spots.sort(function(a,b){return a-b;}); for (var z=0; z<spots.length; z++){ out+=s.substring(last,spots[z])+run; last=spots[z]; }",
 "out+=s.substring(last); out;"
].join("\n");
for (var i = 0; i < layers.length; i++) {
    var l = layers[i];
    if (!l.property("ADBE Text Properties")) { skipped++; continue; }
    var txt = String(l.property("ADBE Text Properties").property("ADBE Text Document").value.text);
    if (!/[ؠ-ي]/.test(txt)) { skipped++; continue; }
    sqSlider(l, "SQ Kashida Amount", params.amount);
    sqSlider(l, "SQ Kashida Duration", params.duration);
    sqSlider(l, "SQ Kashida Bounce", params.bounce);
    sqSlider(l, "SQ Kashida Delay", params.delay);
    sqCheckbox(l, "SQ Kashida Collapse", params.collapse);
    l.property("ADBE Text Properties").property("ADBE Text Document").expression = expr;
    n++;
}
if (!n) return "Select an Arabic text layer.";
return "Kashida Stretch on " + n + " layer" + (n > 1 ? "s" : "") + (skipped ? " (" + skipped + " skipped, not Arabic text)" : "");

// ---- Squeezy add-on helpers (ExtendScript, ES3) ----
function sqFx(l) { return l.property("ADBE Effect Parade"); }
function sqCtrl(l, match, name, v) {
    var p = sqFx(l).property(name);
    if (p && p.matchName !== match) { p.remove(); p = null; }
    if (!p) { p = sqFx(l).addProperty(match); p.name = name; p = sqFx(l).property(name); }
    try { if (v !== undefined && v !== null) p.property(1).setValue(v); } catch (e) {}
    return sqFx(l).property(name);
}
function sqSlider(l, name, v) { return sqCtrl(l, "ADBE Slider Control", name, v); }
function sqCheckbox(l, name, v) { return sqCtrl(l, "ADBE Checkbox Control", name, v ? 1 : 0); }
function sqHex(h) { var n = parseInt(String(h).replace("#", ""), 16); return [((n >> 16) & 255) / 255, ((n >> 8) & 255) / 255, (n & 255) / 255, 1]; }
function sqRemoveFx(l, prefix) {
    var fx = sqFx(l); if (!fx) return;
    for (var i = fx.numProperties; i >= 1; i--) if (String(fx.property(i).name).indexOf(prefix) === 0) fx.property(i).remove();
}
function sqRemoveKids(comp, l, prefix) {
    for (var i = comp.numLayers; i >= 1; i--) {
        var c = comp.layer(i);
        if (c.parent && c.parent.index === l.index && String(c.name).indexOf(prefix) === 0) c.remove();
    }
}
function sqEaseKeys(prop) {
    for (var k = 1; k <= prop.numKeys; k++) {
        var dims = 1; try { var v = prop.keyValue(k); if (v instanceof Array) dims = v.length; } catch (e) {}
        if (prop.propertyValueType === PropertyValueType.TwoD_SPATIAL || prop.propertyValueType === PropertyValueType.ThreeD_SPATIAL) dims = 1;
        var a = [], b = [];
        for (var d = 0; d < dims; d++) { a.push(new KeyframeEase(0, 45)); b.push(new KeyframeEase(0, 45)); }
        try { prop.setTemporalEaseAtKey(k, a, b); } catch (e2) {}
    }
}

// ---- pixel grid reveal (used by Pixel Scan Reveal and Block Flow) ----
// Builds a block matte + optional glowing block layer, both parented to the target layer.
function sqScan(comp, l, o) {
    var r = l.sourceRectAtTime(o.t0, false);
    if (!r || r.width < 1 || r.height < 1) throw new Error(l.name + " has nothing visible at the current time");
    var size = Math.max(4, o.size), cols, rows;
    do { cols = Math.ceil(r.width / size); rows = Math.ceil(r.height / size); if (cols * rows > 700) size *= 1.15; } while (cols * rows > 700);

    sqRemoveKids(comp, l, "SQ Scan ");
    sqRemoveFx(l, "SQ Scan ");
    sqSlider(l, "SQ Scan Progress", 0);
    sqSlider(l, "SQ Scan Random", o.random);
    sqSlider(l, "SQ Scan Glow Band", o.band);
    var pr = sqFx(l).property("SQ Scan Progress").property(1);
    pr.setValueAtTime(o.t0, 0);
    pr.setValueAtTime(o.t0 + o.dur, 100);
    sqEaseKeys(pr);

    var cells = [];
    for (var y = 0; y < rows; y++) for (var x = 0; x < cols; x++) {
        var cx = r.left + (x + 0.5) * size, cy = r.top + (y + 0.5) * size, u;
        var nx = cols > 1 ? x / (cols - 1) : 0, ny = rows > 1 ? y / (rows - 1) : 0;
        switch (o.dir) {
            case "rtl": u = 1 - nx; break;
            case "ttb": u = ny; break;
            case "btt": u = 1 - ny; break;
            case "center": u = Math.min(1, Math.sqrt((nx - 0.5) * (nx - 0.5) + (ny - 0.5) * (ny - 0.5)) / 0.7072); break;
            case "random": u = Math.random(); break;
            default: u = nx;
        }
        cells.push({ x: cx, y: cy, u: u, q: Math.random() });
    }

    function grid(name, glow) {
        var s = comp.layers.addShape();
        s.name = name;
        s.moveBefore(l);
        s.parent = l;
        try { s.property("ADBE Transform Group").property("ADBE Anchor Point").setValue([0, 0]); } catch (e) {}
        try { s.property("ADBE Transform Group").property("ADBE Position").setValue([0, 0]); } catch (e1) { try { s.property("ADBE Transform Group").property("ADBE Position").setValue([0, 0, 0]); } catch (e2) {} }
        var root = function () { return s.property("ADBE Root Vectors Group"); };
        var bs = glow ? size * 0.78 : size + 1;
        var col = glow ? sqHex(o.color) : [1, 1, 1, 1];
        for (var i = 0; i < cells.length; i++) {
            var c = cells[i], k = (c.u * 1).toFixed(4), qq = c.q.toFixed(4);
            var gi = root().addProperty("ADBE Vector Group").propertyIndex;
            var G = function () { return root().property(gi); };
            G().property("ADBE Vectors Group").addProperty("ADBE Vector Shape - Rect");
            G().property("ADBE Vectors Group").property(1).property("ADBE Vector Rect Size").setValue([bs, bs]);
            G().property("ADBE Vectors Group").addProperty("ADBE Vector Graphic - Fill");
            G().property("ADBE Vectors Group").property(2).property("ADBE Vector Fill Color").setValue(col);
            var T = G().property("ADBE Vector Transform Group");
            T.property("ADBE Vector Position").setValue([c.x, c.y]);
            var head = "var P=parent.effect(\"SQ Scan Progress\")(1)/100, R=parent.effect(\"SQ Scan Random\")(1)/100; var k=" + k + "*(1-R)+" + qq + "*R*0.999;";
            G().property("ADBE Vector Transform Group").property("ADBE Vector Group Opacity").expression = glow
                ? head + " var B=Math.max(parent.effect(\"SQ Scan Glow Band\")(1)/100,0.001), d=P-k*(1-B)-B*0.5; (P>0 && P<1 && d>=-B*0.5 && d<B*0.5) ? 100*(1-Math.abs(d)/(B*0.5)) : 0;"
                : head + " (P>=1 || (P>0 && P>=k)) ? 100 : 0;";
        }
        return s;
    }

    var m = grid("SQ Scan Matte · " + l.name, false);
    if (o.glow) {
        var g = grid("SQ Scan Glow · " + l.name, true);
        g.blendingMode = BlendingMode.ADD;
        var gl = sqFx(g).addProperty("ADBE Glo2");
        try { gl.property(3).setValue(Math.max(10, size * 0.8)); gl.property(4).setValue(1.6); } catch (eg) {}
    }
    var done = false;
    try { if (l.setTrackMatte) { l.setTrackMatte(m, TrackMatteType.ALPHA); done = true; } } catch (et) {}
    if (!done) { m.moveBefore(l); l.trackMatteType = TrackMatteType.ALPHA; }
    m.enabled = false;
    return cells.length;
}

if (!comp) return "Open a composition first.";
var ls = [];
for (var i = 0; i < layers.length; i++) {
    var L0 = layers[i];
    if (!L0.property("ADBE Effect Parade") || (L0 instanceof CameraLayer) || (L0 instanceof LightLayer)) continue;
    if (String(L0.name).indexOf("SQ Cylinder") === 0) continue;
    ls.push(L0);
}
if (ls.length < 2) return "Select 2 or more layers for the cylinder.";
var n = ls.length, wsum = 0;
for (var a = 0; a < n; a++) {
    var r = ls[a].sourceRectAtTime(comp.time, false), sc = ls[a].property("ADBE Transform Group").property("ADBE Scale").value;
    wsum += r.width * sc[0] / 100;
}
var R = params.radius > 0 ? params.radius : Math.max(250, (wsum / n) * n * 1.15 / (2 * Math.PI));
var k = 1, nm;
do { nm = "SQ Cylinder " + k; k++; } while ((function () { for (var q = 1; q <= comp.numLayers; q++) if (comp.layer(q).name === nm) return true; return false; })());
var c = comp.layers.addNull();
c.name = nm; c.threeDLayer = true; c.label = 10;
c.property("ADBE Transform Group").property("ADBE Position").setValue([comp.width / 2, comp.height / 2, R]);
c.property("ADBE Transform Group").property("ADBE Rotate X").setValue(params.tilt);
sqSlider(c, "SQ Cyl Radius", R);
sqSlider(c, "SQ Cyl Angle", 0);
sqSlider(c, "SQ Cyl Spin", params.spin);
sqSlider(c, "SQ Cyl Back Blur", params.blur);
sqSlider(c, "SQ Cyl Back Opacity", params.minOpacity);
sqSlider(c, "SQ Cyl Back Darken", params.darken);
sqSlider(c, "SQ Cyl Focus", params.focus);
sqCheckbox(c, "SQ Cyl Snap To Cards", params.snap);
sqSlider(c, "SQ Cyl Hold", params.hold);
sqSlider(c, "SQ Cyl Count", n);

// placement: Angle slider + Spin, or step card-to-card when Snap is on
var head = [
 "var C=parent, R=C.effect(\"SQ Cyl Radius\")(1), N=Math.max(C.effect(\"SQ Cyl Count\")(1),1);",
 "var sp=C.effect(\"SQ Cyl Spin\")(1), rot;",
 "if (C.effect(\"SQ Cyl Snap To Cards\")(1)==1 && sp!=0) {",
 "  var st=360/N, mv=st/Math.abs(sp), hd=Math.max(C.effect(\"SQ Cyl Hold\")(1),0), cy=mv+hd, t=Math.max(time-C.inPoint,0);",
 "  var idx=Math.floor(t/cy), u=Math.min((t-idx*cy)/Math.max(mv,0.001),1); u=u<.5?4*u*u*u:1-Math.pow(-2*u+2,3)/2;",
 "  rot=(idx+u)*st*(sp>0?1:-1);",
 "} else rot=time*sp;",
 "var a=(C.effect(\"SQ Cyl Angle\")(1)+rot+"
].join("\n");

// depth: where this card really is, seen from the active camera (works with null rotation, camera moves, keyframes)
var depth = [
 "var C=parent, R=Math.max(C.effect(\"SQ Cyl Radius\")(1),1);",
 "var p=thisLayer.toWorld(thisLayer.anchorPoint), c=C.toWorld(C.anchorPoint), v=[0,0,1];",
 "try { var cam=thisComp.activeCamera; v=normalize(cam.toWorldVec([0,0,1])); } catch(e) {}",
