// ---- Squeezy add-on helpers (ExtendScript, ES3) ----
function sqFx(l) { return l.property("ADBE Effect Parade"); }
function sqCtrl(l, match, name, v) {
    var p = sqFx(l).property(name);
    if (p && p.matchName !== match) { p.remove(); p = null; }
    if (!p) { p = sqFx(l).addProperty(match); p.name = name; p = sqFx(l).property(name); }
    try { if (v !== undefined && v !== null) p.property(1).setValue(v); } catch (e) {}
    return sqFx(l).property(name);
}
function sqSlider(l, name, v) { return sqCtrl(l, "ADBE Slider Control", name, v); }
function sqCheckbox(l, name, v) { return sqCtrl(l, "ADBE Checkbox Control", name, v ? 1 : 0); }
function sqHex(h) { var n = parseInt(String(h).replace("#", ""), 16); return [((n >> 16) & 255) / 255, ((n >> 8) & 255) / 255, (n & 255) / 255, 1]; }
function sqRemoveFx(l, prefix) {
    var fx = sqFx(l); if (!fx) return;
    for (var i = fx.numProperties; i >= 1; i--) if (String(fx.property(i).name).indexOf(prefix) === 0) fx.property(i).remove();
}
function sqRemoveKids(comp, l, prefix) {
    for (var i = comp.numLayers; i >= 1; i--) {
        var c = comp.layer(i);
        if (c.parent && c.parent.index === l.index && String(c.name).indexOf(prefix) === 0) c.remove();
    }
}
function sqEaseKeys(prop) {
    for (var k = 1; k <= prop.numKeys; k++) {
        var dims = 1; try { var v = prop.keyValue(k); if (v instanceof Array) dims = v.length; } catch (e) {}
        if (prop.propertyValueType === PropertyValueType.TwoD_SPATIAL || prop.propertyValueType === PropertyValueType.ThreeD_SPATIAL) dims = 1;
        var a = [], b = [];
        for (var d = 0; d < dims; d++) { a.push(new KeyframeEase(0, 45)); b.push(new KeyframeEase(0, 45)); }
        try { prop.setTemporalEaseAtKey(k, a, b); } catch (e2) {}
    }
}

// ---- pixel grid reveal (used by Pixel Scan Reveal and Block Flow) ----
// Builds a block matte + optional glowing block layer, both parented to the target layer.
function sqScan(comp, l, o) {
    var r = l.sourceRectAtTime(o.t0, false);
    if (!r || r.width < 1 || r.height < 1) throw new Error(l.name + " has nothing visible at the current time");
    var size = Math.max(4, o.size), cols, rows;
    do { cols = Math.ceil(r.width / size); rows = Math.ceil(r.height / size); if (cols * rows > 700) size *= 1.15; } while (cols * rows > 700);

    sqRemoveKids(comp, l, "SQ Scan ");
    sqRemoveFx(l, "SQ Scan ");
    sqSlider(l, "SQ Scan Progress", 0);
    sqSlider(l, "SQ Scan Random", o.random);
    sqSlider(l, "SQ Scan Glow Band", o.band);
    var pr = sqFx(l).property("SQ Scan Progress").property(1);
    pr.setValueAtTime(o.t0, 0);
    pr.setValueAtTime(o.t0 + o.dur, 100);
    sqEaseKeys(pr);

    var cells = [];
    for (var y = 0; y < rows; y++) for (var x = 0; x < cols; x++) {
        var cx = r.left + (x + 0.5) * size, cy = r.top + (y + 0.5) * size, u;
        var nx = cols > 1 ? x / (cols - 1) : 0, ny = rows > 1 ? y / (rows - 1) : 0;
        switch (o.dir) {
            case "rtl": u = 1 - nx; break;
            case "ttb": u = ny; break;
            case "btt": u = 1 - ny; break;
            case "center": u = Math.min(1, Math.sqrt((nx - 0.5) * (nx - 0.5) + (ny - 0.5) * (ny - 0.5)) / 0.7072); break;
            case "random": u = Math.random(); break;
            default: u = nx;
        }
        cells.push({ x: cx, y: cy, u: u, q: Math.random() });
    }

    function grid(name, glow) {
        var s = comp.layers.addShape();
        s.name = name;
        s.moveBefore(l);
        s.parent = l;
        try { s.property("ADBE Transform Group").property("ADBE Anchor Point").setValue([0, 0]); } catch (e) {}
        try { s.property("ADBE Transform Group").property("ADBE Position").setValue([0, 0]); } catch (e1) { try { s.property("ADBE Transform Group").property("ADBE Position").setValue([0, 0, 0]); } catch (e2) {} }
        var root = function () { return s.property("ADBE Root Vectors Group"); };
        var bs = glow ? size * 0.78 : size + 1;
        var col = glow ? sqHex(o.color) : [1, 1, 1, 1];
        for (var i = 0; i < cells.length; i++) {
            var c = cells[i], k = (c.u * 1).toFixed(4), qq = c.q.toFixed(4);
            var gi = root().addProperty("ADBE Vector Group").propertyIndex;
            var G = function () { return root().property(gi); };
            G().property("ADBE Vectors Group").addProperty("ADBE Vector Shape - Rect");
            G().property("ADBE Vectors Group").property(1).property("ADBE Vector Rect Size").setValue([bs, bs]);
            G().property("ADBE Vectors Group").addProperty("ADBE Vector Graphic - Fill");
            G().property("ADBE Vectors Group").property(2).property("ADBE Vector Fill Color").setValue(col);
            var T = G().property("ADBE Vector Transform Group");
            T.property("ADBE Vector Position").setValue([c.x, c.y]);
            var head = "var P=parent.effect(\"SQ Scan Progress\")(1)/100, R=parent.effect(\"SQ Scan Random\")(1)/100; var k=" + k + "*(1-R)+" + qq + "*R*0.999;";
            G().property("ADBE Vector Transform Group").property("ADBE Vector Group Opacity").expression = glow
                ? head + " var B=Math.max(parent.effect(\"SQ Scan Glow Band\")(1)/100,0.001), d=P-k*(1-B)-B*0.5; (P>0 && P<1 && d>=-B*0.5 && d<B*0.5) ? 100*(1-Math.abs(d)/(B*0.5)) : 0;"
                : head + " (P>=1 || (P>0 && P>=k)) ? 100 : 0;";
        }
        return s;
    }

    var m = grid("SQ Scan Matte · " + l.name, false);
    if (o.glow) {
        var g = grid("SQ Scan Glow · " + l.name, true);
        g.blendingMode = BlendingMode.ADD;
        var gl = sqFx(g).addProperty("ADBE Glo2");
        try { gl.property(3).setValue(Math.max(10, size * 0.8)); gl.property(4).setValue(1.6); } catch (eg) {}
    }
    var done = false;
    try { if (l.setTrackMatte) { l.setTrackMatte(m, TrackMatteType.ALPHA); done = true; } } catch (et) {}
    if (!done) { m.moveBefore(l); l.trackMatteType = TrackMatteType.ALPHA; }
    m.enabled = false;
    return cells.length;
}

if (!comp) return "Open a composition first.";
var ls = [];
for (var i = 0; i < layers.length; i++) if (layers[i].property("ADBE Effect Parade") && String(layers[i].name).indexOf("SQ Scan ") !== 0) ls.push(layers[i]);
if (ls.length < 2) return "Select 2 or more image layers, in the order you want them.";
var t0 = comp.time, hold = params.hold, tr = params.transition, step = params.step;
// stack: later images above earlier ones
for (var a = 1; a < ls.length; a++) ls[a].moveBefore(ls[a - 1]);
for (var j = 0; j < ls.length; j++) {
    var l = ls[j], tin = t0 + j * hold, tout = t0 + (j + 1) * hold + tr;
    l.startTime += tin - l.inPoint;
    if (j < ls.length - 1) { try { l.outPoint = Math.max(tin + 0.1, tout); } catch (e) {} }
    if (j > 0) {
        sqScan(comp, l, { t0: tin, dur: tr, size: params.size, dir: "random", random: 100, band: 22, color: "#FFFFFF", glow: params.glow });
        // previous card steps down in scale while it gets covered
        var prev = ls[j - 1], sc = prev.property("ADBE Transform Group").property("ADBE Scale");
        var base = sc.valueAtTime(tin, false), steps = 3;
        for (var s = 0; s <= steps; s++) {
            var f = 1 - (step / 100) * (s / steps), v = [];
            for (var d = 0; d < base.length; d++) v.push(d < 2 ? base[d] * f : base[d]);
            var kt = tin + tr * (s / steps);
            sc.setValueAtTime(kt, v);
            var ki = sc.nearestKeyIndex(kt);
            try { sc.setInterpolationTypeAtKey(ki, KeyframeInterpolationType.HOLD, KeyframeInterpolationType.HOLD); } catch (e2) {}
        }
    }
}
return "Block Flow: " + ls.length + " images, " + (ls.length - 1) + " block transitions";

// Squeezy add-on: Pixel Scan Reveal (ported from PixelScan_Reveal v1.0 by Kholy)
// runs as function(params, comp, layers)
var SCRIPT_NAME = "Pixel Scan Reveal";
var VERSION = "1.0";
var TAG = "PixelScanRig";
var FOLDER_NAME = "PixelScan Precomps";

// ------------------------------------------------------------------
//  Small helpers
// ------------------------------------------------------------------

function esc(s) {
    return String(s).replace(/\\/g, "\\\\").replace(/"/g, "\\\"");
}

function trimStr(s) {
    return String(s).replace(/^\s+|\s+$/g, "");
}

function shortName(s) {
    s = trimStr(String(s));
    if (s.length > 24) { s = s.substring(0, 24); }
    return s;
}

function makeId() {
    var chars = "abcdefghjkmnpqrstuvwxyz23456789";
    var out = "";
    for (var i = 0; i < 4; i++) {
        out += chars.charAt(Math.floor(Math.random() * chars.length));
    }
    return out;
}

function tagString(id, role) {
    return TAG + ":" + id + ":" + role;
}

function readTag(str) {
    var m = String(str || "").match(/PixelScanRig:([a-z0-9]+):([a-zA-Z]+)/);
    if (!m) { return null; }
    return { id: m[1], role: m[2] };
}

// Find a property by a list of names / matchNames (direct first, then deep search)
function findProp(group, keys) {
    if (!group) { return null; }
    var i, p;
    for (i = 0; i < keys.length; i++) {
        try {
            p = group.property(keys[i]);
            if (p) { return p; }
        } catch (e) {}
    }
    for (i = 0; i < keys.length; i++) {
        p = deepFind(group, keys[i], 0);
        if (p) { return p; }
    }
    return null;
}

function deepFind(group, key, depth) {
    if (depth > 4) { return null; }
    var n = 0;
    try { n = group.numProperties; } catch (e) { return null; }
    for (var i = 1; i <= n; i++) {
        var p = null;
        try { p = group.property(i); } catch (e2) { p = null; }
        if (!p) { continue; }
        if (p.name === key || p.matchName === key) { return p; }
        if (p.propertyType === PropertyType.NAMED_GROUP || p.propertyType === PropertyType.INDEXED_GROUP) {
            var r = deepFind(p, key, depth + 1);
            if (r) { return r; }
        }
    }
    return null;
}

function setVal(group, keys, v) {
    var p = findProp(group, keys);
    if (!p) { return false; }
    try { p.setValue(v); return true; } catch (e) { return false; }
}

function setExpr(group, keys, expr) {
    var p = findProp(group, keys);
    if (!p) { return false; }
    try { p.expression = expr; return true; } catch (e) { return false; }
}

function setColor(prop, rgb) {
    if (!prop) { return; }
    try { prop.setValue([rgb[0], rgb[1], rgb[2], 1]); }
    catch (e) {
        try { prop.setValue([rgb[0], rgb[1], rgb[2]]); } catch (e2) {}
    }
}

function addFx(layer, matchName, name) {
    var parade = layer.property("ADBE Effect Parade");
    if (!parade.canAddProperty(matchName)) { return null; }
    var fx = parade.addProperty(matchName);
    if (name) {
        try { fx.name = name; } catch (e) {}
    }
    return fx;
}

function addCtrl(layer, type, name, value) {
    var matchName = {
        slider:   "ADBE Slider Control",
        angle:    "ADBE Angle Control",
        color:    "ADBE Color Control",
        checkbox: "ADBE Checkbox Control"
    }[type];
    var fx = addFx(layer, matchName, name);
    if (!fx) { return; }
    if (type === "color") { setColor(fx.property(1), value); }
    else { try { fx.property(1).setValue(value); } catch (e) {} }
}

function hexToRgb(hex) {
    hex = String(hex).replace(/[^0-9a-fA-F]/g, "");
    if (hex.length === 3) {
        hex = hex.charAt(0) + hex.charAt(0) + hex.charAt(1) + hex.charAt(1) + hex.charAt(2) + hex.charAt(2);
    }
    if (hex.length !== 6) { return null; }
    var n = parseInt(hex, 16);
    return [((n >> 16) & 255) / 255, ((n >> 8) & 255) / 255, (n & 255) / 255];
}

function intToHex(n) {
    var s = (n & 0xFFFFFF).toString(16).toUpperCase();
    while (s.length < 6) { s = "0" + s; }
    return "#" + s;
}

function getFolder() {
    for (var i = 1; i <= app.project.numItems; i++) {
        var it = app.project.item(i);
        if (it instanceof FolderItem && it.name === FOLDER_NAME) { return it; }
    }
    return app.project.items.addFolder(FOLDER_NAME);
}

function hasTrackMatteSafe(layer) {
    try { return layer.hasTrackMatte === true; } catch (e) { return false; }
}

function setMatte(layer, matte) {
    if (typeof layer.setTrackMatte === "function") {
        // AE 2023+ : matte can be anywhere in the stack
        layer.setTrackMatte(matte, TrackMatteType.ALPHA);
        try { matte.enabled = false; } catch (e) {}
    } else {
        // Legacy: matte must sit directly above
        matte.moveBefore(layer);
        layer.trackMatteType = TrackMatteType.ALPHA;
    }
}

// ------------------------------------------------------------------
//  Expressions
// ------------------------------------------------------------------

// Position of the wipe group (moves the frontier along the chosen direction)
function exprFrontierPos(ref) {
    return [
        "var C = " + ref + ";",
        "var p = C.effect(\"Progress\")(1);",
        "var d = degreesToRadians(C.effect(\"Direction\")(1));",
        "var u = [Math.sin(d), -Math.cos(d)];",
        "var w = thisComp.width, h = thisComp.height;",
        "var E = (w * Math.abs(u[0]) + h * Math.abs(u[1])) / 2;",
        "var M = Math.abs(C.effect(\"Distortion\")(1)) * 0.5 + Math.abs(C.effect(\"Block Size\")(1)) + Math.abs(C.effect(\"Scan Width\")(1)) * 0.5;",
        "var s = linear(p, 0, 100, -E - M, E + M);",
        "[u[0] * s, u[1] * s];"
    ].join("\n");
}

function exprRotation(ref) {
    return ref + ".effect(\"Direction\")(1) - 90;";
}

function exprBandSize(ref, big) {
    return "[Math.max(1, " + ref + ".effect(\"Scan Width\")(1)), " + big + "];";
}

function exprBlocks(ref, axis) {
    var dim = (axis === "h") ? "thisComp.width" : "thisComp.height";
    return "Math.max(1, Math.round(" + dim + " / Math.max(2, " + ref + ".effect(\"Block Size\")(1))));";
}

// ------------------------------------------------------------------
//  Builders
// ------------------------------------------------------------------

// Comp-aligned shape layer holding one rectangle inside a group "Wipe".
// rectSize may be an array or an expression string.
function makeRectShape(comp, name, rectSize, rectPos) {
    var sl = comp.layers.addShape();
    sl.name = name;
    var tr = sl.property("ADBE Transform Group");
    tr.property("ADBE Anchor Point").setValue([0, 0]);
    tr.property("ADBE Position").setValue([comp.width / 2, comp.height / 2]);

    sl.property("ADBE Root Vectors Group").addProperty("ADBE Vector Group");
    var grp = sl.property("ADBE Root Vectors Group").property(1);
    grp.name = "Wipe";

    grp.property("ADBE Vectors Group").addProperty("ADBE Vector Shape - Rect");
    var rect = sl.property("ADBE Root Vectors Group").property(1).property("ADBE Vectors Group").property(1);
    rect.property("ADBE Vector Rect Position").setValue(rectPos);
    if (typeof rectSize === "string") {
        rect.property("ADBE Vector Rect Size").expression = rectSize;
    } else {
        rect.property("ADBE Vector Rect Size").setValue(rectSize);
    }

    sl.property("ADBE Root Vectors Group").property(1).property("ADBE Vectors Group").addProperty("ADBE Vector Graphic - Fill");
    var fill = sl.property("ADBE Root Vectors Group").property(1).property("ADBE Vectors Group").property(2);
    setColor(fill.property("ADBE Vector Fill Color"), [1, 1, 1]);

    return sl;
}

function wireWipe(sl, ref) {
    var gtr = sl.property("ADBE Root Vectors Group").property(1).property("ADBE Vector Transform Group");
    gtr.property("ADBE Vector Position").expression = exprFrontierPos(ref);
    gtr.property("ADBE Vector Rotation").expression = exprRotation(ref);
}

// Turbulent Displace + Mosaic: the jagged pixel edge (same settings on both mattes
// so the scan strip sits exactly on the reveal frontier)
function addMatteFx(sl, ref) {
    var td = addFx(sl, "ADBE Turbulent Displace", "PS Turbulence");
    if (td) {
        setExpr(td, ["Amount", "ADBE Turbulent Displace-0002"], ref + ".effect(\"Distortion\")(1);");
        setExpr(td, ["Size", "ADBE Turbulent Displace-0003"], ref + ".effect(\"Distortion Size\")(1);");
        setVal(td, ["Complexity", "ADBE Turbulent Displace-0005"], 8);
        setExpr(td, ["Evolution", "ADBE Turbulent Displace-0006"], ref + ".effect(\"Evolution\")(1);");
    }
    var mo = addFx(sl, "ADBE Mosaic", "PS Mosaic");
    if (mo) {
        setExpr(mo, ["Horizontal Blocks", "ADBE Mosaic-0001"], exprBlocks(ref, "h"));
        setExpr(mo, ["Vertical Blocks", "ADBE Mosaic-0002"], exprBlocks(ref, "v"));
        setExpr(mo, ["Sharp Colors", "ADBE Mosaic-0003"], ref + ".effect(\"Sharp Blocks\")(1);");
    }
}

function buildController(comp, name, id, o) {
    var ctrl = comp.layers.addNull(comp.duration);
    ctrl.name = name;
    ctrl.comment = tagString(id, "ctrl");
    try { ctrl.label = 2; } catch (e) {}

